73	    private String householdId;
74	
75	    @Column(name = "namesake_count")
76	    private Integer namesakeCount;
77	
78	    @Column(name = "bulk_signup_warning")
79	    private Boolean bulkSignupWarning;
80	
81	    @Column(name = "capacity_warning")
82	    private Boolean capacityWarning;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "postcode")
88	    private String postcode;
89	
90	    @Column(name = "possible_duplicate")
91	    private Boolean possibleDuplicate;
92	
93	    @Column(name = "possible_duplicate_of")
94	    private Integer possibleDuplicateOf;
95	
96	    @Column(name = "deleted", nullable = false)
97	    private boolean deleted;
98	
99	    @Column(name = "membership_level_cap")
100	    private Integer membershipLevelCap;
101	
102	    @Transient
103	    private boolean declaredHouseholdMember;
104	
105	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
106	    private Set<Pet> pets;
107	
108	    public String getTitle() {
109	        return this.title;
110	    }
111	
112	    public void setTitle(String title) {
113	        this.title = title;
114	    }
115	
116	    /**
117	     * The owner's salutation: the {@link #getTitle() title} and last name separated by a
118	     * single space (e.g. {@code "DR Who"}), or just the last name when no title is on file.
119	     * Derived from the owner's own fields, so it stays consistent with them.
120	     */
121	    @Transient
122	    public String getSalutation() {
123	        if (this.title == null || this.title.isEmpty()) {
124	            return this.getLastName();
125	        }
126	        return this.title + " " + this.getLastName();
127	    }
128	
129	    public String getAddress() {
130	        return this.address;
131	    }
132	
133	    public void setAddress(String address) {
134	        this.address = address;
135	    }
136	
137	    public String getAddressLine1() {
138	        return this.addressLine1;
139	    }
140	
141	    public void setAddressLine1(String addressLine1) {
142	        this.addressLine1 = addressLine1;
143	    }
144	
145	    public String getAddressLine2() {
146	        return this.addressLine2;
147	    }
148	
149	    public void setAddressLine2(String addressLine2) {
150	        this.addressLine2 = addressLine2;
151	    }
152	
153	    public String getCity() {
154	        return this.city;
155	    }
156	
157	    public void setCity(String city) {
158	        this.city = city;
159	    }
160	
161	    public String getTelephone() {
162	        return this.telephone;
163	    }
164	
165	    public void setTelephone(String telephone) {
166	        this.telephone = telephone;
167	    }
168	
169	    public String getEmail() {
170	        return this.email;
171	    }
172	
173	    public void setEmail(String email) {
174	        this.email = email;
175	    }
176	
177	    public LocalDate getRegistrationDate() {
178	        return this.registrationDate;
179	    }
180	
181	    public void setRegistrationDate(LocalDate registrationDate) {
182	        this.registrationDate = registrationDate;
183	    }
184	
185	    public LocalDate getBirthDate() {
186	        return this.birthDate;
187	    }
188	
189	    public void setBirthDate(LocalDate birthDate) {
190	        this.birthDate = birthDate;
191	    }
192	
193	    public String getCustomerCode() {
194	        return this.customerCode;
195	    }
196	
197	    public void setCustomerCode(String customerCode) {
198	        this.customerCode = customerCode;
199	    }
200	
201	    /**
202	     * The owner's primary identifier: the single value that identifies the owner across
203	     * the system, currently the {@link #getCustomerCode() customer code}. Callers that
204	     * need "the owner's identity" (such as the audit trail) should read this rather than
205	     * the customer code directly, so that when the customer code is later unified into the
206	     * member id the identifier follows in one place.
207	     */
208	    @Transient
209	    public String getPrimaryIdentifier() {
210	        return this.customerCode;
211	    }
212	
213	    public String getHouseholdId() {
214	        return this.householdId;
215	    }
216	
217	    public void setHouseholdId(String householdId) {
218	        this.householdId = householdId;
219	    }
220	
221	    public Integer getNamesakeCount() {
222	        return this.namesakeCount;
223	    }
224	
225	    public void setNamesakeCount(Integer namesakeCount) {
226	        this.namesakeCount = namesakeCount;
227	    }
228	
229	    public Boolean getBulkSignupWarning() {
230	        return this.bulkSignupWarning;
231	    }
232	
233	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
234	        this.bulkSignupWarning = bulkSignupWarning;
235	    }
236	
237	    /**
238	     * Whether this owner's city already held enough owners, when this owner was created,
239	     * to be approaching its hard capacity limit (between 40 and 49 owners, one short of
240	     * the limit of 50). Stamped at creation, it flags a city filling towards capacity.
241	     */
242	    public Boolean getCapacityWarning() {
243	        return this.capacityWarning;
244	    }
245	
246	    public void setCapacityWarning(Boolean capacityWarning) {
247	        this.capacityWarning = capacityWarning;
248	    }
249	
250	    public Integer getHouseholdSize() {
251	        return this.householdSize;
252	    }
253	
254	    public void setHouseholdSize(Integer householdSize) {
255	        this.householdSize = householdSize;
256	    }
257	
258	    public String getPostcode() {
259	        return this.postcode;
260	    }
261	
262	    public void setPostcode(String postcode) {
263	        this.postcode = postcode;
264	    }
265	
266	    /**
267	     * Whether this owner deliberately declared, when created, that it shares its
268	     * household with an existing owner (the request's {@code sharesHousehold} flag).
269	     * A declared member is created despite occupying an existing household and is not
270	     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
271	     */
272	    @Transient
273	    public boolean isDeclaredHouseholdMember() {
274	        return this.declaredHouseholdMember;
275	    }
276	
277	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
278	        this.declaredHouseholdMember = declaredHouseholdMember;
279	    }
280	
281	    /**
282	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
283	     * existing owner: not a hard duplicate, but sharing that owner's phonetic last name
284	     * (see {@link Soundex}) and postcode while its {@link #getIdentityKey() identity key}
285	     * differs. See {@link #getPossibleDuplicateOf()}.
286	     */
287	    public Boolean getPossibleDuplicate() {
288	        return this.possibleDuplicate;
289	    }
290	
291	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
292	        this.possibleDuplicate = possibleDuplicate;
293	    }
294	
295	    /**
296	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
297	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
298	     */
299	    public Integer getPossibleDuplicateOf() {
300	        return this.possibleDuplicateOf;
301	    }
302	
303	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
304	        this.possibleDuplicateOf = possibleDuplicateOf;
305	    }
306	
307	    /**
308	     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
309	     * deleting the owner retains its row and flags it {@code true}. A deleted owner is
310	     * still retrievable but is ignored by the create endpoint's duplicate/identity checks.
311	     */
312	    public boolean isDeleted() {
313	        return this.deleted;
314	    }
315	
316	    public void setDeleted(boolean deleted) {
317	        this.deleted = deleted;
318	    }
319	
320	    /**
321	     * The ceiling on this owner's {@link #getMembershipLevel() membership level}, stamped
322	     * when the owner is created as one above the highest membership level then held by an
323	     * existing member of its household, or null when the owner had no existing household
324	     * member and so is subject to no ceiling. See {@link #getMembershipLevel()}.
325	     */
326	    public Integer getMembershipLevelCap() {
327	        return this.membershipLevelCap;
328	    }
329	
330	    public void setMembershipLevelCap(Integer membershipLevelCap) {
331	        this.membershipLevelCap = membershipLevelCap;
332	    }
333	
334	    /**
335	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
336	     * is the last two digits of the registration date's fiscal year (see {@link FiscalYear};
337	     * e.g. {@code "NSW-1A2B3C4D-M26"}). Derived from the owner's own fields, so it stays
338	     * consistent with them, including its {@link #getFiscalYear() fiscal year}.
339	     */
340	    @Transient
341	    public String getMembershipNumber() {
342	        if (this.customerCode == null || this.registrationDate == null) {
343	            return null;
344	        }
345	        return String.format("%s-M%02d", this.customerCode, FiscalYear.shortYearOf(this.registrationDate));
346	    }
347	
348	    /**
349	     * The owner's fiscal year: the {@code 'FY<YY>'} label of the fiscal year (which starts
350	     * on 1 July) that their business-day-adjusted registration date falls in (see
351	     * {@link FiscalYear}). Derived from the owner's own registration date, so it stays
352	     * consistent with it; null until a registration date is on file.
353	     */
354	    @Transient
355	    public String getFiscalYear() {
356	        if (this.registrationDate == null) {
357	            return null;
358	        }
359	        return FiscalYear.labelFor(this.registrationDate);
360	    }
361	
362	    /**
363	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
364	     * over the digits of the customer code. Derived from the owner's own customer code,
365	     * so it stays consistent with it.
366	     */
367	    @Transient
368	    public Integer getCheckDigit() {
369	        if (this.customerCode == null) {
370	            return null;
371	        }
372	        return LuhnCheckDigit.of(this.customerCode);
373	    }
374	
375	    /**
376	     * The owner's membership points, starting at zero: two points are added when an email is
377	     * on file, one more when the owner is unique (namesake count of zero), two more for a
378	     * household of three or more, and three more when the owner has accrued more than a fiscal
379	     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
380	     * consistent with them.
381	     */
382	    @Transient
383	    public Integer getMembershipPoints() {
384	        int points = 0;
385	        boolean hasEmail = this.email != null && !this.email.isEmpty();
386	        if (hasEmail) {
387	            points += 2;
388	        }
389	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
390	        if (unique) {
391	            points += 1;
392	        }
393	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
394	        if (largeHousehold) {
395	            points += 2;
396	        }
397	        boolean tenured = this.registrationDate != null
398	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
399	        if (tenured) {
400	            points += 3;
401	        }
402	        return points;
403	    }
404	
405	    /**
406	     * The owner's membership level, a number from 1 to 4, derived from their
407	     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}), then
408	     * held down to its {@link #getMembershipLevelCap() household ceiling} when one applies.
409	     * Derived from the owner's own fields, so it stays consistent with them.
410	     */
411	    @Transient
412	    public Integer getMembershipLevel() {
413	        int level = MembershipLevel.forPoints(getMembershipPoints());
414	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
415	            return this.membershipLevelCap;
416	        }
417	        return level;
418	    }
419	
420	    /**
421	     * The owner's locality: the canonical region, taken as the region segment of the
422	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
423	     * consistent with the owner's identity. When no customer code has been assigned yet
424	     * it falls back to resolving the region directly from the postcode and city (see
425	     * {@link RegionResolver}), the same rule the customer code itself is built from.
426	     */
427	    @Transient
428	    public String getLocality() {
429	        if (this.customerCode != null) {
430	            int separator = this.customerCode.indexOf('-');
431	            if (separator > 0) {
432	                return this.customerCode.substring(0, separator);
433	            }
434	        }
435	        return RegionResolver.regionFor(this.postcode, this.city);
436	    }
437	
438	    /**
439	     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
440	     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
441	     * stays consistent with the owner's region. Null when the locality has no known timezone.
442	     */
443	    @Transient
444	    public String getTimezone() {
445	        return RegionTimezoneTable.timezoneFor(getLocality());
446	    }
447	
448	    /**
449	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
450	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
451	     * stays consistent with them.
452	     */
453	    @Transient
454	    public String getContactPreference() {
455	        boolean hasEmail = this.email != null && !this.email.isEmpty();
456	        return hasEmail ? "EMAIL" : "PHONE";
457	    }
458	
459	    /**
460	     * The owner's telephone formatted for human display: the stored E.164 number
461	     * rendered as its country calling code, a space and the national digits grouped
462	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
463	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
464	     * consistent with it. See {@link TelephoneFormatter}.
465	     */
466	    @Transient
467	    public String getTelephoneDisplay() {
468	        return TelephoneFormatter.toDisplay(this.telephone);
469	    }
470	
471	    /**
472	     * The owner's identity key: the single derived value used to detect duplicate owners,
473	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + (email or empty) + '|' +
474	     * soundex(lastName)} (see {@link Soundex}). Two owners are hard duplicates only when
475	     * their identity keys are equal; because the telephone is part of the key, members of
476	     * one household with different telephones stay distinct. Derived from the owner's own
477	     * fields, so it stays consistent with them.
478	     */
479	    @Transient
480	    public String getIdentityKey() {
481	        String telephonePart = this.telephone == null ? "" : this.telephone;
482	        String emailPart = this.email == null ? "" : this.email;
483	        return Sha256.hex(telephonePart + "|" + emailPart + "|" + Soundex.of(this.getLastName()));
484	    }
485	
486	    /**
487	     * The owner's age band relative to their registration date: {@code "MINOR"} when
488	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
489	     * Derived from the owner's own birth and registration dates, so it stays consistent
490	     * with them; null until a birth date is on file. See {@link AgeBand}.
491	     */
492	    @Transient
493	    public String getAgeBand() {
494	        if (this.birthDate == null || this.registrationDate == null) {
495	            return null;
496	        }
497	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
498	    }
499	
500	    /**
501	     * Normalize the registration date before persisting: default it to the server's
502	     * current date when none was supplied, then roll it forward onto a business day so
503	     * every newly persisted owner is registered on a weekday.
504	     */
505	    @PrePersist
506	    void normalizeRegistrationDate() {
507	        if (this.registrationDate == null) {
508	            this.registrationDate = LocalDate.now();
509	        }
510	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
511	    }
512	
513	    protected Set<Pet> getPetsInternal() {
514	        if (this.pets == null) {
515	            this.pets = new HashSet<>();
516	        }
517	        return this.pets;
518	    }
519	
520	    protected void setPetsInternal(Set<Pet> pets) {
521	        this.pets = pets;
522	    }
523	
524	    public List<Pet> getPets() {
525	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
526	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
527	        return Collections.unmodifiableList(sortedPets);
528	    }
529	
530	    public void setPets(List<Pet> pets) {
531	        this.pets = new HashSet<>(pets);
532	    }
533	
534	    public void addPet(Pet pet) {
535	        getPetsInternal().add(pet);
536	        pet.setOwner(this);
537	    }
538	
539	    /**
540	     * Return the Pet with the given name, or null if none found for this Owner.
541	     *
542	     * @param name to test
543	     * @return true if pet name is already in use
544	     */
545	    public Pet getPet(String name) {
546	        return getPet(name, false);
547	    }
548	
549	    /**
