557	        for (Pet pet : getPetsInternal()) {
558	            if (!ignoreNew || !pet.isNew()) {
559	                String compName = pet.getName();
560	                compName = compName.toLowerCase();
561	                if (compName.equals(name)) {
562	                    return pet;
563	                }
